  <title>Cat FAQ</title>
  <style>
    :root {
      --bg: #f5f7fb;
      --panel: rgba(255, 255, 255, 0.82);
      --panel-strong: #ffffff;
      --text: #172033;
      --muted: #5a667f;
      --line: rgba(23, 32, 51, 0.1);
      --accent: #5b7cff;
      --accent-strong: #3b5bdb;
      --shadow: 0 20px 50px rgba(27, 39, 94, 0.12);
      --radius-lg: 28px;
      --radius-md: 18px;
      --radius-sm: 14px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(91, 124, 255, 0.18), transparent 28%),
        radial-gradient(circle at top right, rgba(79, 209, 197, 0.18), transparent 24%),
        linear-gradient(180deg, #f8faff 0%, #eef2f8 100%);
      padding: 32px 20px;
    }

