      background: var(--panel);
      backdrop-filter: blur(16px);
      border: 1px solid rgba(255, 255, 255, 0.7);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .hero {
      padding: 56px 28px 28px;
      background:
        linear-gradient(135deg, rgba(91, 124, 255, 0.12), rgba(79, 209, 197, 0.08)),
        var(--panel-strong);
      border-bottom: 1px solid var(--line);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(91, 124, 255, 0.1);
      color: var(--accent-strong);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.02em;
      text-transform: uppercase;
    }

    h1 {
      margin: 18px 0 12px;
      font-size: clamp(2rem, 5vw, 3.8rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .hero p {
      margin: 0;
      max-width: 640px;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .faq-list {
      padding: 24px;
      display: grid;
      gap: 16px;
    }

    .example {
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.88);
      border: 1px solid rgba(91, 124, 255, 0.12);
      box-shadow: 0 10px 30px rgba(25, 37, 77, 0.08);
      overflow: hidden;
    }

    .question {
      margin: 0;
    }

    .trigger {
      width: 100%;
      border: 0;
      background: transparent;
      color: inherit;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      text-align: left;
      padding: 22px 24px;
      cursor: pointer;
      font: inherit;
      font-size: 1.02rem;
      font-weight: 700;
