        padding-left: 18px;
        padding-right: 18px;
      }
    }
  </style>
</head>
<body>
  <div id="app" class="page-shell"></div>

  <script>
    const faqItems = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel safe and content, but they can also purr to self-soothe when stressed or recovering. It is a versatile sound that can signal comfort, communication, or calm."
      },
      {
        question: "How much sleep do cats need?",
        answer: "Most cats sleep between 12 and 16 hours a day, with kittens and older cats often sleeping even more. Their bursts of activity are usually balanced by frequent naps throughout the day."
      },
      {
        question: "Why do cats knead blankets or laps?",
        answer: "Kneading is a behavior that starts in kittenhood and often continues into adult life. It is usually a sign of comfort, routine, and affection, and some cats also use it to mark a favorite spot with scent glands in their paws."
      },
      {
        question: "What should cats eat?",
        answer: "Cats are obligate carnivores, so they need food that is rich in animal-based protein and formulated for feline nutrition. Fresh water should always be available, and treats should stay as a small part of the overall diet."
      },
      {
        question: "Why do cats stare out the window?",
        answer: "Windows give cats a safe way to watch birds, insects, people, and movement outside. This kind of visual enrichment keeps them mentally engaged and can help indoor cats feel more stimulated."
      }
    ];

    function FAQItem({ question, answer, index }) {
      const panelId = `faq-panel-${index}`;
      const buttonId = `faq-button-${index}`;

      return `
        <div class="example">
          <h2 class="question">
            <button
              id="${buttonId}"
              class="trigger"
              type="button"
              aria-expanded="false"
              aria-controls="${panelId}"
            >
              <span>${question}</span>
              <span class="icon" aria-hidden="true">+</span>
            </button>
          </h2>
          <div
            id="${panelId}"
            class="details"
            role="region"
            aria-labelledby="${buttonId}"
            hidden
          >
            <p>${answer}</p>
          </div>
        </div>
      `;
    }

    function Hero() {
      return `
        <section class="hero">
          <span class="eyebrow">Cat care FAQ</span>
          <h1>Everything people ask about cats, in one calm and tidy place.</h1>
          <p>
            Browse quick answers to common cat questions. Each topic starts collapsed, so the page stays
            easy to scan while still offering more detail on demand.
          </p>
        </section>
      `;
    }

    function FAQList(items) {
      return `
        <section class="faq-list" aria-label="Frequently asked questions about cats">
          ${items.map((item, index) => FAQItem({ ...item, index })).join("")}
        </section>
      `;
    }

    function App() {
      return `
        <main class="page">
          ${Hero()}
          ${FAQList(faqItems)}
        </main>
      `;
    }

